#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
void *allocate_array(size_t count, size_t element_size)
{
    if (count == 0 || element_size == 0) return NULL;
    if (count > SIZE_MAX / element_size) return NULL;
    return malloc(count * element_size);
}
int main(void) { int *p = allocate_array(8, sizeof *p); if (p == NULL) return 1; p[0] = 42; free(p); return 0; }

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
struct packet { size_t length; unsigned char data[]; };
struct packet *packet_create(size_t count)
{
    size_t payload, total; struct packet *p;
    if (count > SIZE_MAX / sizeof(unsigned char)) return NULL;
    payload = count * sizeof(unsigned char);
    if (payload > SIZE_MAX - sizeof(struct packet)) return NULL;
    total = sizeof(struct packet) + payload;
    p = malloc(total); if (p == NULL) return NULL;
    p->length = count; return p;
}
int main(void) { struct packet *p = packet_create(16); if (p == NULL) return 1; free(p); return 0; }
